<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Infra 可视化原型 v3 · 单超节点统一视图</title>
<style>
:root{
  --bg:#0d1117; --panel:#161b22; --panel2:#010409; --border:#30363d; --border2:#484f58;
  --txt:#c9d1d9; --dim:#8b949e; --blue:#58a6ff; --dblue:#1f6feb; --purple:#a371f7;
  --green:#3fb950; --red:#f85149; --orange:#d29922; --teal:#39c5cf;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{background:var(--bg);color:var(--txt);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;overflow:hidden;font-size:13px}
#app{display:flex;flex-direction:column;height:100vh}
/* ===== 顶栏 ===== */
#topbar{height:50px;flex-shrink:0;display:flex;align-items:center;gap:10px;padding:0 14px;background:var(--panel);border-bottom:1px solid var(--border)}
#topbar .title{font-size:15px;font-weight:700;background:linear-gradient(90deg,var(--blue),var(--purple));-webkit-background-clip:text;background-clip:text;color:transparent;margin-right:8px;white-space:nowrap}
#topbar .grp{display:flex;align-items:center;gap:5px}
#topbar .grplab{font-size:11px;color:var(--dim);margin-right:2px}
button{cursor:pointer;background:#21262d;color:var(--txt);border:1px solid var(--border2);border-radius:6px;padding:4px 10px;font-size:12px;transition:.2s;white-space:nowrap}
button:hover{background:#30363d}
button.on{background:var(--dblue);border-color:var(--blue);color:#fff}
button.lens-TP.on{background:#0f4a50;border-color:var(--teal)}
button.lens-PP.on{background:#5a4310;border-color:var(--orange)}
button.lens-DP.on{background:#173a6b;border-color:var(--blue)}
button.lens-EP.on{background:#3c2a63;border-color:var(--purple)}
button.warn.on{background:#67060c;border-color:var(--red)}
#alertbar{display:none;margin-left:auto;background:#67060c;border:1px solid var(--red);color:#ffdcd7;border-radius:6px;padding:3px 10px;font-size:12px}
#alertbar.show{display:block;animation:pulse 1.4s infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.45}}
/* ===== 主区 ===== */
#main{flex:1;display:flex;min-height:0}
/* ---- 左：2D 层级剖面 ---- */
#left{width:430px;flex-shrink:0;border-right:1px solid var(--border);background:var(--panel2);overflow-y:auto;position:relative;padding:10px 12px 16px}
#left h3{font-size:12px;color:var(--dim);font-weight:400;margin-bottom:8px}
#left h3 b{color:#fff}
.lvrow{position:relative;border:1px solid var(--border);border-radius:8px;background:var(--panel);padding:6px 8px;cursor:pointer;transition:border-color .2s, box-shadow .2s}
.lvrow:hover{border-color:var(--border2)}
.lvrow.focus{border-color:var(--blue);box-shadow:0 0 10px rgba(88,166,255,.35)}
.lvrow .hd{display:flex;align-items:baseline;gap:6px}
.lvrow .lv{font-size:11px;font-weight:700;color:var(--blue);width:24px;flex-shrink:0}
.lvrow .nm{font-size:12px;color:#fff}
.lvrow .ct{font-size:11px;color:var(--dim);margin-left:auto;font-family:ui-monospace,monospace}
.lvrow.ghost{opacity:.75}
.lvrow .body{margin-top:5px}
.gap{position:relative;height:26px;display:flex;align-items:center;justify-content:flex-end;gap:6px;padding-right:4px}
.badge{font-size:10px;padding:1px 8px;border-radius:9px;border:1px solid var(--border2);color:var(--dim);background:#161b22;transition:.25s;position:relative;z-index:5}
.badge.b-TP{border-color:#1b7c86;color:#7ee0e8}
.badge.b-PP{border-color:#8a6416;color:#e3b341}
.badge.b-DP{border-color:#1f6feb;color:#9ecbff}
.badge.b-EP{border-color:#6e40c9;color:#d2a8ff}
.badge.b-ANOM{border-color:var(--red);color:#ffdcd7;display:none}
.badge.live{box-shadow:0 0 10px currentColor;color:#fff}
.badge.b-ANOM.show{display:inline-block;animation:pulse 1.2s infinite}
canvas.strip{display:block;width:100%;image-rendering:pixelated;border-radius:4px}
.inset{display:flex;gap:8px;align-items:center;margin-top:5px}
.inset .zoom{display:flex;gap:3px}
.inset .zoom i{display:block;width:16px;height:16px;border-radius:3px;border:1px solid var(--border2);background:#21262d}
.inset .lab{font-size:10px;color:var(--dim)}
.ph{display:flex;gap:6px;align-items:center}
.ph .die{flex:1;border:1px dashed var(--border2);border-radius:6px;padding:4px 8px;font-size:10px;color:var(--dim);text-align:center}
.ph .cg{border:1px solid;border-radius:4px;font-size:10px;padding:3px 8px}
.cg.v{border-color:var(--purple);color:#d2a8ff;background:#1c1333}
.cg.c{border-color:var(--red);color:#ffb3ac;background:#2d0f0e}
.cg.u{border-color:var(--orange);color:#e3b341;background:#2b2008}
#commsvg{position:absolute;top:0;left:0;pointer-events:none;z-index:4}
@keyframes dashmove{to{stroke-dashoffset:-22}}
.flow{stroke-dasharray:7 4;animation:dashmove .9s linear infinite;fill:none}
/* ---- 右：3D ---- */
#right{flex:1;position:relative;min-width:0;background:radial-gradient(ellipse at 50% 30%,#0f1626 0%,#010409 75%)}
#stage{position:absolute;inset:0;width:100%;height:100%}
#formctl{position:absolute;top:10px;right:12px;display:flex;gap:6px;z-index:5}
#viewlab{position:absolute;top:12px;left:14px;z-index:5;font-size:12px;color:var(--dim);pointer-events:none}
#viewlab b{color:#fff}
#probe{position:absolute;left:14px;bottom:12px;z-index:5;background:rgba(1,4,9,.85);border:1px solid var(--border);border-radius:8px;padding:8px 12px;font-size:11px;color:var(--dim);min-width:230px;pointer-events:none}
#probe b{color:#fff}
#probe .lg{color:var(--teal);font-family:ui-monospace,monospace}
#hud{position:absolute;right:12px;bottom:12px;z-index:5;background:rgba(1,4,9,.85);border:1px solid var(--border);border-radius:8px;padding:8px 12px;font-size:11px;color:var(--dim);width:210px;pointer-events:none}
#hud .bus{margin-top:4px}
#hud .busbar{height:7px;background:#21262d;border-radius:4px;overflow:hidden;margin-top:2px}
#hud .busbar i{display:block;height:100%;border-radius:4px;transition:width .4s}
/* ===== 底部时间轴 ===== */
#footer{height:58px;flex-shrink:0;display:flex;align-items:center;gap:12px;padding:0 14px;background:var(--panel);border-top:1px solid var(--border)}
#phasetrack{flex:1;display:flex;height:26px;border-radius:6px;overflow:hidden;position:relative;cursor:pointer}
.pseg{flex:1;display:flex;align-items:center;justify-content:center;font-size:11px;color:#fff;opacity:.35;transition:opacity .3s;border-right:1px solid #0d1117}
.pseg.on{opacity:1}
.pseg.s-TP{background:#0f4a50}.pseg.s-PP{background:#5a4310}.pseg.s-EP{background:#3c2a63}.pseg.s-DP{background:#173a6b}
#playhead{position:absolute;top:-4px;bottom:-4px;width:2px;background:#fff;box-shadow:0 0 8px #fff;pointer-events:none}
#phaselab{font-size:12px;color:var(--orange);width:210px;text-align:right}
</style>
</head>
<body>
<div id="app">
  <div id="topbar">
    <span class="title">AI Infra 统一视图 v3</span>
    <span class="grp"><span class="grplab">策略透镜</span>
      <button class="lensbtn on" data-lens="NONE">无·健康度</button>
      <button class="lensbtn lens-TP" data-lens="TP">TP×8</button>

