    for(let i=0;i<3;i++)
      paths.push(`<path class="flow" d="${arcPath(r3.x+20+i*30, y, r3.x+r3.w-30-i*30, y, 46+i*12)}" stroke="${COL.DP}" stroke-width="1.6"/>`);
    paths.push(`<path class="flow" d="${arcPath(r4.x+60, r4.y, r5.x+150, r5.y+r5.h, 22)}" stroke="${COL.DP}" stroke-width="1.3" opacity=".7"/>`); }
  commsvg.innerHTML = paths.join('');
  // 台阶徽章点亮
  const map = { TP:'#bdTP', PP:'#bdPP', EP:'#bdEP', DP:'#bdDP' };
  $$('.badge').forEach(b=>b.classList.remove('live'));
  $(map[ph]).classList.add('live');
  if(ph==='DP') $('#bdDPx').classList.add('live');
  $('#bdAnom').classList.toggle('show', S.anomaly);
  if(S.anomaly && ph==='EP') $('#bdAnom').classList.add('live');
  // 异常时 L5 的 Pod1 染红（专家被越界调度到相邻超节点）
  const p1 = $('#pod5-1');
  if(p1){ p1.style.borderColor = S.anomaly?'#f85149':'#30363d';
          p1.style.color = S.anomaly?'#ffdcd7':'#8b949e';
          p1.style.background = S.anomaly?'#3d0c0e':'#161b22'; }
}
function touchLeft(){ renderL3(); renderL2(); renderChipZoom(); renderProbe(); }
/* ================= 右侧：3D 视图（物理层级形态 ⇄ 逻辑魔方形态） ================= */
const stage = $('#stage'), gx = stage.getContext('2d');
let W=0, H=0, DPR=1;
function resize(){ const r = $('#right').getBoundingClientRect();
  DPR = window.devicePixelRatio||1; W = r.width; H = r.height;
  stage.width = W*DPR; stage.height = H*DPR; gx.setTransform(DPR,0,0,DPR,0,0); }
window.addEventListener('resize', ()=>{ resize(); });
// 右侧物理形态 = L7→L0 八层全量同屏堆叠（左侧选层只高亮，不筛选内容）
const BAND = { L7:{yc:.045,h:26}, L6:{yc:.13,h:48}, L5:{yc:.215,h:38}, L4:{yc:.30,h:44},
               L3:{yc:.455,h:114}, L2:{yc:.655,h:94}, L1:{yc:.815,h:40}, L0:{yc:.915,h:48} };
const bandY = lv => BAND[lv].yc*H;
const la = lv => S.level===lv ? 1 : .42;                    // 非高亮层压暗，但永远在场
function hostStackPos(h){ const r=(h/32)|0, c=h%32;
  return { x: W/2 + (c-r)*4.6, y: bandY('L3') + (c+r-31)*1.35 }; }
function chipStackPos(cId){ const row=(cId/256)|0, col=cId%256;
  return { x: W/2 + (col-127.5)*1.56 + (row-15.5)*0.5, y: bandY('L2') + (row-15.5)*2.2 }; }
function cubePosChip(cId){ const h=hostOf(cId);
  const tp=slotOf(cId), pp=ppOf(h), dp=dpOf(h);
  return { x: W/2 + (tp-3.5)*30 - (dp-31.5)*5.4,
           y: H*0.5 + (tp-3.5)*8 + (dp-31.5)*3.1 - (pp-7.5)*15 }; }
const l6Pos = i => ({ x: W/2 + ((i%8)-((i/8)|0))*17, y: bandY('L6') + ((i%8)+((i/8)|0)-7)*4.2 });
const l5Pos = i => ({ x: W/2 + (i-3.5)*52, y: bandY('L5') });
const ease = k => k<.5 ? 2*k*k : 1-Math.pow(-2*k+2,2)/2;
function pulseK(){ return S.playing ? .5+.5*Math.sin(performance.now()/180) : 0; }
// 阶段参与判定（右侧脉冲）：当前阶段哪些 host 在通信
function hostActive(h){ const ph = PHASES[S.phase].id;
  if(!S.playing) return false;
  if(ph==='TP') return true;
  if(ph==='PP') return ppOf(h) === (((S.t*4%1)*16)|0);
  if(ph==='EP') return !!isExpertHost[h];
  if(ph==='DP') return dpOf(h)%8 === (((S.t*4%1)*8)|0);
  return false; }
function drawDiamond(x,y,w,hh,col,glow){
  gx.beginPath(); gx.moveTo(x,y-hh); gx.lineTo(x+w,y); gx.lineTo(x,y+hh); gx.lineTo(x-w,y); gx.closePath();
  gx.fillStyle = col; if(glow){ gx.shadowColor=col; gx.shadowBlur=8; } gx.fill(); gx.shadowBlur=0; }
function renderStage(){
  gx.clearRect(0,0,W,H);
  const m = ease(S.morph);
  if(m < 0.02){ renderStack(1, true); }
  else { if(m < 0.98) renderStack((1-m)*0.8, false);       // 堆叠淡出，芯片飞向魔方
         renderMorphChips(m); }
}
// 物理形态：八层全量堆叠。每层画该层真实对象；左侧选中层只提亮 + 描边
function planeLabel(lv, text){
  gx.fillStyle = S.level===lv ? '#fff' : '#6e7681'; gx.font='11px sans-serif'; gx.textAlign='left';
  gx.fillText(text, 14, bandY(lv) - BAND[lv].h/2 + 4); }
function highlightBand(lv){ if(S.level!==lv) return;
  gx.strokeStyle='rgba(88,166,255,.65)'; gx.lineWidth=1;
  gx.strokeRect(8, bandY(lv)-BAND[lv].h/2, W-16, BAND[lv].h); }
function renderStack(baseA, withChips){
  const pk = pulseK();
  // L7 · Global ×1
  gx.globalAlpha = baseA*la('L7');
