    for(let c=0;c<N_CHIP;c++){ const p = chipStackPos(c);
      gx.fillStyle = chipColor(c); gx.fillRect(p.x-.7, p.y-.95, 1.4, 1.9); }
    for(let s=0;s<8;s++){ const p = chipStackPos(S.focusHost*8+s);
      gx.strokeStyle='#9ecbff'; gx.lineWidth=.7; gx.strokeRect(p.x-1.4,p.y-1.6,2.8,3.2); }
    const fc = chipStackPos(S.focusChip);
    gx.strokeStyle='#fff'; gx.lineWidth=1; gx.strokeRect(fc.x-2,fc.y-2.2,4,4.4); }
  highlightBand('L2');
  // L1 · Die（占位）
  gx.globalAlpha = baseA*la('L1');
  planeLabel('L1','L1 · Die（可选）· 结构占位，950DT 未公开');
  gx.setLineDash([6,4]); gx.strokeStyle='#8b949e'; gx.lineWidth=1;
  gx.beginPath(); gx.moveTo(W/2-150,bandY('L1')+9); gx.lineTo(W/2-110,bandY('L1')-9);
  gx.lineTo(W/2+150,bandY('L1')-9); gx.lineTo(W/2+110,bandY('L1')+9); gx.closePath(); gx.stroke(); gx.setLineDash([]);
  highlightBand('L1');
  // L0 · Core-Group（占位：V / C / CPU）
  gx.globalAlpha = baseA*la('L0');
  planeLabel('L0','L0 · Core-Group · 结构占位（算子最终落点）');
  [['V','#a371f7'],['C','#f85149'],['CPU','#d29922']].forEach((it,i)=>{
    const x = W/2+(i-1)*110, y = bandY('L0')+4;
    gx.setLineDash([4,3]); gx.strokeStyle=it[1]; gx.lineWidth=1;
    gx.strokeRect(x-42,y-11,84,22); gx.setLineDash([]);
    gx.fillStyle=it[1]; gx.font='10px sans-serif'; gx.textAlign='center'; gx.fillText(it[0], x, y+4); gx.textAlign='left'; });
  highlightBand('L0');
  // 焦点路径纵向连线：本超节点 → 本Pod → 焦点Host → 焦点芯片 → Die → Core
  gx.globalAlpha = baseA*.5; gx.strokeStyle='#58a6ff'; gx.lineWidth=1; gx.setLineDash([3,4]);
  const pts = [ {x:W/2,y:bandY('L7')+8}, l6Pos(0), l5Pos(0), {x:W/2,y:bandY('L4')+4},
    hostStackPos(S.focusHost), chipStackPos(S.focusChip), {x:W/2,y:bandY('L1')}, {x:W/2,y:bandY('L0')+4} ];
  gx.beginPath(); gx.moveTo(pts[0].x, pts[0].y);
  for(let i=1;i<pts.length;i++) gx.lineTo(pts[i].x, pts[i].y);
  gx.stroke(); gx.setLineDash([]); gx.globalAlpha = 1;
}
// 魔方形态 / Morphing：8192 颗芯片从 L2 层平面飞向 [DP,PP,TP] 逻辑晶格
function renderMorphChips(m){
  gx.globalAlpha = 1;
  for(let c=0;c<N_CHIP;c++){
    const a = chipStackPos(c), b = cubePosChip(c);
    const x = a.x+(b.x-a.x)*m, y = a.y+(b.y-a.y)*m;
    gx.fillStyle = chipColor(c);
    gx.fillRect(x-1.1, y-1.1, 2.2, 2.2);
    if(hostOf(c)===S.focusHost){ gx.strokeStyle='#fff'; gx.lineWidth=.7; gx.strokeRect(x-1.8,y-1.8,3.6,3.6); } }
  if(m>0.9){
    gx.fillStyle='#8b949e'; gx.font='11px sans-serif'; gx.textAlign='left';
    gx.fillText('逻辑魔方形态 · 8192 坐标 · X=TP×8  Y=PP×16  Z=DP×64', 16, H-52);
    gx.fillText('同一批芯片：物理地址 ⇄ 逻辑坐标 双向映射（Morphing 即映射本身）', 16, H-36); }
}
// 右侧拾取：物理形态下 L3 层（1024 Host）与 L2 层（8192 芯片）可悬停/点选
stage.addEventListener('mousemove', ev=>{
  if(S.morph>0.05){ return setHover(-1,''); }
  const r = stage.getBoundingClientRect(), x=ev.clientX-r.left, y=ev.clientY-r.top;
  const y3=bandY('L3'), y2=bandY('L2');
  if(Math.abs(y-y3) <= BAND.L3.h/2){                        // 逆等距：c-r=u, c+r=v
    const u=(x-W/2)/4.6, v=(y-y3)/1.35+31;
    const c=Math.round((u+v)/2), rr=Math.round((v-u)/2);
    if(rr>=0&&rr<32&&c>=0&&c<32) return setHover(rr*32+c,'3D');
    return setHover(-1,''); }
  if(Math.abs(y-y2) <= BAND.L2.h/2){
    const row=Math.round((y-y2)/2.2+15.5);
    const col=Math.round((x-W/2-(row-15.5)*0.5)/1.56+127.5);
    if(row>=0&&row<32&&col>=0&&col<256) return setHover(hostOf(row*256+col),'3D');
    return setHover(-1,''); }
  setHover(-1,''); });
stage.addEventListener('mouseleave', ()=>setHover(-1,''));
stage.addEventListener('click', ()=>{
  if(S.hoverHost>=0){ S.focusHost=S.hoverHost; S.focusChip=S.focusHost*8; touchLeft(); } });
/* ================= 全局状态机：透镜 / 形态 / 时间轴 / 异常 ================= */
$$('.lensbtn').forEach(b=>b.onclick = ()=>{
  S.lens = b.dataset.lens;
  $$('.lensbtn').forEach(x=>x.classList.toggle('on', x===b));
  touchLeft(); });
let morphTarget = 0;
$('#btnPhys').onclick = ()=>{ morphTarget=0; formBtns(); };
$('#btnCube').onclick = ()=>{ morphTarget=1; formBtns(); };
function formBtns(){ $('#btnPhys').classList.toggle('on', morphTarget===0);
  $('#btnCube').classList.toggle('on', morphTarget===1);
  S.form = morphTarget? 'cube':'phys'; }
$('#btnAnom').onclick = ()=>{ S.anomaly=!S.anomaly;
  $('#btnAnom').classList.toggle('on', S.anomaly);
  $('#alertbar').classList.toggle('show', S.anomaly);
  drawArcs(); touchLeft(); };
// 时间轴：一个训练 Step = TP → PP → EP → DP
$('#btnPlay').onclick = ()=>{ S.playing=!S.playing;
  $('#btnPlay').textContent = S.playing?'⏸ 暂停':'▶ 播放';
  $('#btnPlay').classList.toggle('on', S.playing); };
$('#phasetrack').addEventListener('click', ev=>{
  const r = $('#phasetrack').getBoundingClientRect();
  S.t = Math.min(.999, Math.max(0,(ev.clientX-r.left)/r.width)); syncPhase(); });
function syncPhase(){
  const p = Math.min(3, (S.t*4)|0);
  if(p!==S.phase){ S.phase=p; drawArcs(); touchLeft(); }
  $('#playhead').style.left = (S.t*100)+'%';
  $$('.pseg').forEach((el,i)=>el.classList.toggle('on', i===S.phase));
  $('#phaselab').textContent = PHASES[S.phase].name;
  renderHUD(); }
/* ---- 信息面板 ---- */
function renderViewlab(){
  const t = { L7:'L7 · Global ×1', L6:'L6 · SuperCluster ×64 超节点', L5:'L5 · Service Pool ×8 Pod',
    L4:'L4 · Atlas 950 超节点 ×1（8192 NPU）', L3:'L3 · Host ×1024', L2:'L2 · Chip ×8192',
    L1:'L1 · Die（占位）', L0:'L0 · Core-Group（占位）' };
  $('#viewlab').innerHTML = `八层全量常驻 · 高亮 <b>${t[S.level]}</b> · 形态：${S.form==='phys'?'物理层级堆叠':'逻辑魔方'}`; }
function renderProbe(){
  const h = S.hoverHost>=0 ? S.hoverHost : S.focusHost;
  const exp = isExpertHost[h] ? (isExpertHost[h]===2?' · 热点专家⚠':' · MoE 专家') : '';
  const an = (S.anomaly && isAnomHost[h]) ? ' · <b style="color:#f85149">EP 越界成员</b>' : '';
  $('#probe').innerHTML =
    `<b>Host ${h}</b>${S.hoverHost>=0?'（悬停）':'（焦点）'} · 计算柜 ${cabOf(h)} / 槽位 ${h%8}${exp}${an}<br>
     逻辑坐标 <span class="lg">[DP${dpOf(h)}, PP${ppOf(h)}, TP0-7]</span> · 健康度 ${(100-health[h]*40).toFixed(0)}%<br>
     当前算子：${S.playing? (PHASES[S.phase].id==='TP'?'MatMul + AllReduce(UB)':PHASES[S.phase].id==='PP'?'Send/Recv 激活接力':PHASES[S.phase].id==='EP'?'Top-K 路由 + AllToAll':'梯度 AllReduce'):'空闲 / 未播放'}`; }
function renderHUD(){
  const ph = PHASES[S.phase];
  const load = S.playing ? ph.load*(0.85+0.3*Math.abs(Math.sin(performance.now()/700))) : 0.08;
  const anomX = S.anomaly && ph.id==='EP';
  $('#hud').innerHTML =
    `<b style="color:#fff">COMM BUS 遥测</b> · 主导链路随阶段切换
     <div class="bus">${ph.bus}${anomX?' + <span style="color:#f85149">跨 Pod 光链路(越界)</span>':''}
       <div class="busbar"><i style="width:${Math.min(100,load*100)|0}%;background:${anomX?'#f85149':'#39c5cf'}"></i></div>
       <div style="margin-top:3px">带宽占用 ${(load*100)|0}% · ${ph.id==='TP'?'节点内 UB':'UB 平面'}${anomX?' · 拥塞告警':''}</div>
     </div>`; }
/* ---- 主循环 ---- */
let last = performance.now();
function loop(now){
  const dt = (now-last)/1000; last = now;
  if(S.playing){ S.t = (S.t + dt/16) % 1; syncPhase(); }
  if(Math.abs(S.morph-morphTarget)>0.001){
    S.morph += Math.sign(morphTarget-S.morph)*Math.min(dt/0.9, Math.abs(morphTarget-S.morph));
    renderViewlab(); }
  renderStage();
  requestAnimationFrame(loop); }
/* ---- 初始化 ---- */
resize(); setLevel('L4'); formBtns(); syncPhase();
renderL3(); renderL2(); renderChipZoom(); renderProbe(); renderHUD(); drawArcs();
window.addEventListener('resize', drawArcs);
requestAnimationFrame(loop);
</script>
</body>
</html>

