/* ============ 10 模型侧：整网分隔映射（层×卡 ⇄ 物理货架 双向索引） ============ */
/* 教学模型：8 卡 rank0-7；8 层 L1-L8；PP=2（段0=卡0-3/层L1-L4，段1=卡4-7/层L5-L8）；TP=4（层内列切）；L4=MoE(EP)；DP=整网复制 */
const MM_ROWS=8, MM_COLS=8;
const mmState={selRow:null,selCol:null,showDP:true};
const mmStageOfLayer=r=>r<4?0:1;              // 层 r(0-7) 属于哪个 PP 段
const mmStageOfCard=c=>c<4?0:1;               // 卡 c(0-7) 属于哪个 PP 段
const mmFilled=(r,c)=>mmStageOfLayer(r)===mmStageOfCard(c);   // 该卡是否承载该层
const mmIsEP=(r,c)=>r===3&&mmFilled(r,c);     // L4 是 MoE 层 → EP 分派
function mmBuild(){
  const g=document.getElementById('mmGrid');
  const colW=`46px`;
  let h=`<div style="display:grid;grid-template-columns:34px repeat(${MM_COLS},1fr);gap:3px;min-width:420px">`;
  // 头行：DP 标签 + 卡号
  h+=`<div></div>`;
  for(let c=0;c<MM_COLS;c++)h+=`<div id="mmH-${c}" style="text-align:center;font-size:10px;color:var(--dim);cursor:pointer;padding:2px 0;border-radius:4px" onclick="mmPickCol(${c})">r${c}</div>`;
  // PP 段括号行
  h+=`<div></div><div style="grid-column:span 4;border-top:2px solid var(--purple);text-align:center;font-size:9px;color:var(--purple)">PP 段0 · 卡0-3</div><div style="grid-column:span 4;border-top:2px solid var(--purple);text-align:center;font-size:9px;color:var(--purple)">PP 段1 · 卡4-7</div>`;
  // 层行
  for(let r=0;r<MM_ROWS;r++){
    h+=`<div id="mmL-${r}" style="font-size:10px;color:var(--dim);cursor:pointer;display:flex;align-items:center;justify-content:flex-end;padding-right:3px;border-radius:4px" onclick="mmPickRow(${r})">L${r+1}</div>`;
    for(let c=0;c<MM_COLS;c++){
      h+=`<div id="mmC-${r}-${c}" onclick="mmPickCell(${r},${c})" title="L${r+1} × rank${c}" style="height:26px;border-radius:3px;cursor:pointer;transition:.2s;display:flex;align-items:center;justify-content:center;font-size:8px"></div>`;
    }
  }
  h+=`</div>`;
  g.innerHTML=h;
}
function mmRacks(){
  const host=document.getElementById('mmRacks');host.innerHTML='';
  for(let s=0;s<2;s++){
    let inner='';for(let c=s*4;c<s*4+4;c++)inner+=`<div class="lgpu" id="mmR-${c}" onclick="mmPickCol(${c})">rank${c}</div>`;
    host.innerHTML+=`<div class="lrack"><h5>PP 段${s} · 卡${s*4}-${s*4+3}</h5>${inner}</div>`;
  }
}
function mmMem(card){
  document.getElementById('mmMemTitle').textContent=`单卡显存构成 · rank${card}`;
  // 段：权重分片 / 优化器 m / 优化器 v / 激活 / KV·其他（数值随卡略变，教学示意）
  const isMoE=card<4;   // 段0 含 MoE 层 → 专家权重更重、优化器状态更大
  const segs=isMoE
    ? [['权重分片(含专家)',26,'var(--dblue)'],['优化器 m',18,'#6e40c9'],['优化器 v',18,'#8957e5'],['激活值',22,'var(--green)'],['KV·其他',16,'var(--dim)']]
    : [['权重分片',22,'var(--dblue)'],['优化器 m',16,'#6e40c9'],['优化器 v',16,'#8957e5'],['激活值',30,'var(--green)'],['KV·其他',16,'var(--dim)']];
  let bar=`<div style="display:flex;height:20px;border-radius:5px;overflow:hidden;border:1px solid var(--border)">`;
  segs.forEach(([n,v,c])=>bar+=`<div title="${n} ${v}%" style="width:${v}%;background:${c}"></div>`);
  bar+=`</div>`;
  let leg='<div style="margin-top:8px;display:flex;flex-direction:column;gap:3px">';
  segs.forEach(([n,v,c])=>leg+=`<div style="display:flex;align-items:center;gap:6px;font-size:10.5px"><span style="width:9px;height:9px;border-radius:2px;background:${c};flex-shrink:0"></span><span style="flex:1;color:var(--txt)">${n}</span><span style="font-family:monospace;color:var(--dim)">${v}%</span></div>`);
  leg+='</div>';
  document.getElementById('mmMem').innerHTML=bar+leg;
  document.getElementById('mmMem').innerHTML+=`<div style="font-size:9.5px;color:var(--dim);margin-top:6px">优化器状态(m+v)常是权重的 2-4×；激活值占显存大头，重算可换回一部分。</div>`;
}
function mmShard(card){
  const stage=mmStageOfCard(card),base=stage*4;
  document.getElementById('mmShardTitle').textContent=`张量切分网格 · L${stage*4+2} 权重 W[H×4H]（PP 段${stage}）`;
  const host=document.getElementById('mmShard');host.innerHTML='';
  for(let i=0;i<4;i++){const c=base+i,onCard=c===card;
    host.innerHTML+=`<div onclick="mmPickCol(${c})" style="flex:1;border-radius:3px;cursor:pointer;display:flex;align-items:flex-end;justify-content:center;padding-bottom:4px;font-size:9px;color:#fff;transition:.2s;background:var(--dblue);opacity:${onCard?1:0.4};outline:${onCard?'2px solid #fff':'none'}">rank${c}</div>`;
  }
  document.getElementById('mmShardNote').innerHTML=card!=null
    ? `rank${card} 只持有第 ${card-base+1}/4 片 · 必须与同段另 3 卡做 <b style="color:var(--txt)">AllReduce</b> 才拼回完整 W`
    : '← 一个完整权重被列切 4 片 →';
}
function mmPaint(){
  const {selRow,selCol,showDP}=mmState;
  // DP 外圈
  document.getElementById('mmWrap').style.outline=showDP?'2px dashed var(--green)':'none';
  document.getElementById('mmWrap').style.outlineOffset='3px';
  // 头/层标签高亮
  for(let c=0;c<MM_COLS;c++){const el=document.getElementById('mmH-'+c);el.style.background=selCol===c?'var(--dblue)':'transparent';el.style.color=selCol===c?'#fff':'var(--dim)';}
  for(let r=0;r<MM_ROWS;r++){const el=document.getElementById('mmL-'+r);el.style.background=selRow===r?'var(--purple)':'transparent';el.style.color=selRow===r?'#fff':'var(--dim)';}
  // 单元
  for(let r=0;r<MM_ROWS;r++)for(let c=0;c<MM_COLS;c++){
    const el=document.getElementById('mmC-'+r+'-'+c);
    if(!mmFilled(r,c)){el.style.background='#161b22';el.style.border='1px dashed #2a3140';el.textContent='';el.style.opacity=0.5;el.style.outline='none';continue;}
    el.style.opacity=1;el.style.border='none';
    el.style.background=mmIsEP(r,c)?'var(--orange)':'var(--dblue)';
    el.textContent=mmIsEP(r,c)?'E':'';
    // 选中行/列的高亮：其余压暗
    const hit=(selRow===r)||(selCol===c);
    const anySel=selRow!=null||selCol!=null;
    el.style.outline=hit?'2px solid #fff':'none';
    el.style.filter=(anySel&&!hit)?'brightness(0.5)':'none';
  }
  // 物理货架
  for(let c=0;c<MM_COLS;c++){const el=document.getElementById('mmR-'+c);if(!el)continue;
    const lit=(selCol===c)||(selRow!=null&&mmFilled(selRow,c));
    el.style.background=lit?(selRow!=null&&mmIsEP(selRow,c)?'var(--orange)':'var(--dblue)'):'#21262d';
    el.style.color=lit?'#fff':'var(--dim)';el.style.outline=selCol===c?'2px solid #fff':'none';
  }
}
function mmDescribe(){
  const {selRow,selCol}=mmState;let d;
  if(selRow!=null){
    const cards=[];for(let c=0;c<MM_COLS;c++)if(mmFilled(selRow,c))cards.push('rank'+c);
    const ep=selRow===3;
    d=`选中 <b style="color:var(--purple)">L${selRow+1}</b>（PP 段${mmStageOfLayer(selRow)}）→ 它${ep?'是 MoE 层，按 <b style="color:var(--orange)">EP</b> 把专家分派到':'的权重被 <b style="color:var(--dblue)">TP</b> 列切 4 片，分到'} ${cards.join('、')}。物理货架上这组卡已亮起——这就是"点整网的一层，看它摊在哪些卡"。`;
  }else if(selCol!=null){
    const layers=[];for(let r=0;r<MM_ROWS;r++)if(mmFilled(r,selCol))layers.push('L'+(r+1));
    d=`选中 <b style="color:var(--dblue)">rank${selCol}</b>（PP 段${mmStageOfCard(selCol)}）→ 它承载 ${layers.join('、')} 各层的 TP 切片（第 ${selCol%4+1}/4 片）。右侧显存条=这张卡装了什么，切分网格=它在权重里分到哪一片。反查完成。`;
  }else{
    d='点击矩阵的行（层）或列（卡），或右侧物理卡，观察整网的分隔如何在物理卡上落地。TP/PP/EP=真·分隔整网（裁切线）；DP=整网复制（外圈虚线）。';
  }
  document.getElementById('mmDesc').innerHTML=d;
}
function mmSync(){mmPaint();mmDescribe();}
function mmPickRow(r){mmState.selRow=(mmState.selRow===r?null:r);mmState.selCol=null;mmSync();}
function mmPickCol(c){mmState.selCol=(mmState.selCol===c?null:c);mmState.selRow=null;mmMem(c);mmShard(c);mmSync();}
function mmPickCell(r,c){if(!mmFilled(r,c))return;mmPickCol(c);}
function mmToggleDP(){mmState.showDP=!mmState.showDP;document.getElementById('mmDP').classList.toggle('on',mmState.showDP);mmPaint();}
mmBuild();mmRacks();mmMem(0);mmShard(0);mmState.selCol=null;mmSync();
</script>
</div>
</body>
</html>

