  SD.lr.push(i<10? i/10*3 : 3*Math.pow(.985,i-10));
  SD.mfu.push(52+Math.sin(i/6)*3); }
function stepSparks(){ SD.t++;
  SD.loss.push(Math.max(2.2, SD.loss[SD.loss.length-1]*.999+(Math.random()-.5)*.1)); SD.loss.shift();
  SD.lr.push(SD.lr[SD.lr.length-1]*.999); SD.lr.shift();
  SD.mfu.push(52+Math.sin(SD.t/6)*3+(S.anomaly?-9:0)+Math.random()); SD.mfu.shift();
  SD.dots = SD.dots.map(d=>d-1).filter(d=>d>2);
