    const mn=Math.min(...pts), mx=Math.max(...pts);
    sg.strokeStyle=color; sg.lineWidth=1.2; sg.beginPath();
    pts.forEach((v,i)=>{ const x=x0+i*w/(pts.length-1), y=y0+h-(v-mn)/(mx-mn||1)*h;
      i?sg.lineTo(x,y):sg.moveTo(x,y); });
    sg.stroke();
    (dots||[]).forEach(d=>{ if(d<0||d>=pts.length) return;
      const x=x0+d*w/(pts.length-1), y=y0+h-(pts[d]-mn)/(mx-mn||1)*h;
      sg.fillStyle='#f85149'; sg.beginPath(); sg.arc(x,y,2.5,0,7); sg.fill(); });
    sg.fillStyle='#6e7681'; sg.font='9px sans-serif'; sg.textAlign='left'; sg.fillText(name,x0,7); };
  draw(SD.loss,2,'#f85149','Loss · Scale溢出=红点',SD.dots);
  draw(SD.lr,118,'#d29922','LR');
  draw(SD.mfu,234,'#3fb950','MFU'+(S.anomaly?' ↓':''));
}
