const mainJs = html.match(/<script>([\s\S]*?)<\/script>/)[1];
const cleaned = html.replace(/<script src=[^>]+><\/script>/,'').replace(/<script>[\s\S]*?<\/script>/,'');
const dom = new JSDOM(cleaned, { pretendToBeVisual:true, runScripts:'outside-only' });
const { window } = dom;
window.HTMLCanvasElement.prototype.getContext = function(){
  const t = { measureText:()=>({width:10}) };
  return new Proxy(t, { get:(o,k)=> k in o ? o[k] : ((...a)=>undefined), set:()=>true });
};
const THREE = require('three/build/three.js');
THREE.WebGLRenderer = class { constructor(){} setPixelRatio(){} setSize(){} render(){} };
window.THREE = THREE;
let rafQ = [];
window.requestAnimationFrame = fn => { rafQ.push(fn); return rafQ.length; };
window.step = (n=1)=>{ for(let i=0;i<n;i++){ const q=rafQ; rafQ=[]; q.forEach(f=>f(performance.now())); } };
const errs = [];
window.addEventListener('error', e=>errs.push(e.message+' @ '+(e.filename||'')+':'+e.lineno));
try { window.eval(mainJs + "\n;window.__T={get S(){return S},setFilter,setLevel,get Wgt(){return Wgt},filterInfo,drawArcs,renderL3,renderL2};"); } catch(e){ console.log('SCRIPT THREW:', e.message); console.log(e.stack.split('\n').slice(0,5).join('\n')); }
window.step(3);
module.exports = { window, errs };
if(require.main === module){
  const doc = window.document;
  const g = expr => window.eval('__T.'+expr);
  console.log('=== init: level=%s form=%s errors=%j', g('S.level'), g('S.form'), errs);
  for(const lv of ['L6','L5','L7','L3','L2','L4']){
